import { Component, OnInit, Input } from '@angular/core';
import { WsdataService } from './../wsdata.service';
import * as Hls from 'hls.js';
import { environment } from '../../environments/environment';

@Component({
    selector: 'app-hlsplayer',
    templateUrl: './hlsplayer.component.html',
    styleUrls: ['./hlsplayer.component.less']
})
export class HlsPlayerComponent implements OnInit {

    url: string;

    constructor(private wsdataService: WsdataService) {
        if (!environment.production) {
            //this.url = 'http://' + environment.dev_ip + '/hls/playlist.m3u8';
            this.url = 'http://195.190.97.130:8081/app/stream/playlist.m3u8'
        } else {
            const loc = window.location;
            //this.url = 'http://' + loc.host + '/hls/playlist.m3u8';
            this.url = 'http://195.190.97.130:8081/app/stream/playlist.m3u8'
        }
    }

    ngOnInit(): void {
        this.start_player();
    }

    start_player(): void {
        if (Hls.isSupported()) {
            const hls = new Hls();
            hls.loadSource(this.url);
            const video = document.getElementById('video') as HTMLVideoElement;
            hls.attachMedia(video);
            hls.on(Hls.Events.MANIFEST_PARSED, () => {
                const videotag = document.getElementById('video') as HTMLVideoElement;
                videotag.muted = true;
                const promise = videotag.play();
                if (promise !== undefined) {
                    promise.then(_ => {
                    }).catch(error => {
                    });
                }
            });
          }
    }

}
