import { Component, AfterViewInit, ViewChild } from '@angular/core';
import { WsdataService } from '../wsdata.service';
import { NgForm } from '@angular/forms';
import { environment } from '../../environments/environment';

@Component({
    selector: 'app-system',
    templateUrl: './system.component.html',
    styleUrls: ['./system.component.less']
})
export class SystemComponent implements AfterViewInit {
    public networkSettings = this.wsData.copyNetworkSettings();
    @ViewChild('systemForm', {static: false}) public systemForm: NgForm;

    public systemData = this.wsData.settingsData;
    public diagnosticsData = this.wsData.diagnosticsData;
    public logUrl = '';
    public codeword = '';
    public confirmCodeword = '';

    newdata(): void {
        if (this.systemForm.form.pristine) {
            this.systemData = this.wsData.copySettings();
            this.networkSettings = this.wsData.copyNetworkSettings();
        }
    }

    constructor(public wsData: WsdataService) {
        this.wsData.subscribeNewData(() => this.newdata());
        if (!environment.production) {
            this.logUrl = 'http://' + environment.dev_ip + '/log/';
        } else {
            const loc = window.location;
            this.logUrl = 'http://' + loc.host + '/log/';
        }
    }

    ngAfterViewInit(): void {
        this.newdata();
    }

    resetForm(): void {
        this.systemForm.form.markAsPristine();
        this.newdata();
    }

    sendForm(): void {
        this.wsData.readSettings(this.systemData);
        this.wsData.sendSet();
        this.systemForm.form.markAsPristine();
    }

    EventLogOpen(): void {
        window.open(this.logUrl);
    }

    SetTime(): void {
        this.wsData.sendTime();
    }

    setNewCodeword(val: string): void {
        this.wsData.send_codeword(val);
    }

    reboot(): void {
        this.wsData.sendReboot();
    }

    public sendIpForm(): void {
        this.wsData.readNetworkSettings(this.networkSettings);
        this.wsData.sendNetworkSettings();
        this.systemForm.form.markAsPristine();
    }

    ConfigExport() {
        this.wsData.sendConfigExport();
    }

    ConfigImport() {
        const dlAnchorElem = document.getElementById('jsonFile');
        dlAnchorElem.click();
    }

    ConfigRead(e) {
        const files = e.target.files;

        const jsonFile = files[0];
        const reader = new FileReader();
        reader.addEventListener('load', (loadEvent: Event) => {
        try {
            this.wsData.sendConfigImport(JSON.parse(reader.result as string));
        } catch (error) {
            console.error(error);
        }
        });
        reader.readAsText(jsonFile);

    }

}
