import { Component, OnInit, Input, Output, EventEmitter, OnChanges, SimpleChanges } from '@angular/core';
import { SVG, Svg } from '@svgdotjs/svg.js';
import { WsdataService,  } from '../wsdata.service';
import { Router } from '@angular/router';
import { LayoutData, WindowData, WindowConfig, LabelConfig } from '../datatypes';

interface WindowPos {
    x: number;
    y: number;
    scale_x: number;
    scale_y: number;
}

interface GridPos {
    x: number;
    y: number;
}

interface Rect {
    x: number;
    y: number;
    w: number;
    h: number;
}

@Component({
    selector: 'app-layouteditor',
    templateUrl: './layouteditor.component.html',
    styleUrls: ['./layouteditor.component.less']
})
export class LayoutEditorComponent implements OnInit, OnChanges {
    @Input() data: LayoutData;
    @Input() addType: number;
    @Output() changed = new EventEmitter<WindowData>();
    @Output() remove = new EventEmitter<WindowData>();

    SVG_WIDTH = 800;
    SVG_HEIGHT = 450;

    draw: Svg;

    // Логика выбора ячеек
    selectState = 0;
    selectStart: GridPos = {x: 0, y: 0};
    selectEnd: GridPos = {x: 0, y: 0};

    private colorBackground = '#b1bfca';
    private colorGrid = '#e3f2fd';
    private colorActive = '#607d8b';
    private colorNew = '#4b636e';
    private gridSize = -1;

    constructor(private router: Router, private wsdata: WsdataService) {
    }

    ngOnInit(): void {
        this.draw = SVG().addTo('#svg').size(this.SVG_WIDTH, this.SVG_HEIGHT);
        this.drawLayout(true);
    }

    getGridBoxSize(v: GridPos): Rect {
        const ret: Rect = {
            w: (this.SVG_WIDTH - 5) / this.data.grid - 5,
            h: (this.SVG_HEIGHT - 5) / this.data.grid - 5,
            x: 5,
            y: 5,
        };

        ret.x += (ret.w + ret.x) * v.x;
        ret.y += (ret.h + ret.y) * v.y;

        return ret;
    }

    getWindowBoxSize(v: WindowData): Rect {
        const ret: Rect = {
            w: (this.SVG_WIDTH - 3) * (v.scale_x + 1 ) / this.data.grid - 3,
            h: (this.SVG_HEIGHT - 3) * (v.scale_y + 1 ) / this.data.grid - 3,
            x: 3,
            y: 3,
        };

        ret.x += ((this.SVG_WIDTH - 3) / this.data.grid) * v.x;
        ret.y += ((this.SVG_HEIGHT - 3) / this.data.grid) * v.y;

        return ret;
    }

    windowToRect(value: WindowData): Rect {
        return {
            x: value.x,
            y: value.y,
            w: value.x + value.scale_x,
            h: value.y + value.scale_y,
        };
    }

    isInsideWindow(v: GridPos, window: WindowPos): boolean {
        if ((v.x >= window.x) && (v.x <= window.x + window.scale_x)
            &&
            (v.y >= window.y) && (v.y <= window.y + window.scale_y)) {
            return true;
        } else {
            return false;
        }
    }

    isWindowIntersecting(a: WindowPos, b: WindowPos): boolean {
        if (this.isInsideWindow({x: a.x, y: a.y}, b)
                || this.isInsideWindow({x: a.x + a.scale_x, y: a.y}, b)
                || this.isInsideWindow({x: a.x, y: a.y + a.scale_y}, b)
                || this.isInsideWindow({x: a.x + a.scale_x, y: a.y + a.scale_y}, b)
                || ((a.x > b.x) && (a.x < b.x + b.scale_x) && (a.y < b.y) && (a.y + a.scale_y >= b.y + b.scale_y))
                || ((a.x < b.x) && (a.x + a.scale_x > b.x + b.scale_x) && (a.y >= b.y) && (a.y + a.scale_y <= b.y + b.scale_y))
                ) {
                return true;
            } else {
                return false;
            }
    }

    getAnyWindowIntersect(v: WindowPos): boolean {
        if (this.isWindowIntersecting(this.wsdata.clockData.pos, v) && (this.wsdata.clockData.enable)) {
            return true;
        }
        if (this.isWindowIntersecting(this.wsdata.timerData.pos, v) && (this.wsdata.timerData.enable)) {
            return true;
        }
        const r = this.data.inputs.filter((window: WindowConfig): boolean => {
            if (this.isWindowIntersecting(window.pos, v)) {
                return true;
            } else {
                return false;
            }
        });
        if (r.length > 0) {
            return true;
        }

        const rlabel = this.data.labels.filter((window: LabelConfig): boolean => {
            if (this.isWindowIntersecting(window.pos, v)) {
                return true;
            } else {
                return false;
            }
        });
        if (rlabel.length > 0) {
            return true;
        }

        return false;
    }

    shortName(name: string): string {
        return name.substring(0, 10);
    }

    drawGrid(): void {
        if (this.gridSize === this.data.grid){
            return;
        }
        this.gridSize = this.data.grid;
        // background
        this.draw.rect(this.SVG_WIDTH, this.SVG_HEIGHT).attr({ fill: this.colorBackground })
        .mouseup((data) => this.bkgMouseUp());

        // сетка
        for (let y = 0; y < this.data.grid; y++) {
            for (let x = 0; x < this.data.grid; x++) {
                const boxSize: Rect = this.getGridBoxSize({x, y});
                const r = this.draw.rect(boxSize.w, boxSize.h).attr({ fill: this.colorGrid })
                .move(boxSize.x, boxSize.y)
                .attr('data-x', x).attr('data-y', y)
                .mousedown((data) => this.gridMouseDown(data, {x, y}))
                .mouseup((data) => this.gridMouseUp({x, y}))
                .on('update', (data) => this.gridUpdate(data, {x, y}))
                .mouseout((data) => this.gridMouseOut(data, {x, y}))
                .mouseover((data) => this.gridMouseOver(data, {x, y}))
                ;
            }
        }
    }

    drawLayout(drawAll = false): void {
        let closeSize = 30;
        let textOffset = 25;
        if (this.data.grid > 4) {
            closeSize = 25;
            textOffset = 10;
        }
        if (this.data.grid > 5) {
            closeSize = 18;
            textOffset = 10;
        }

        this.drawGrid();

        for (let i = 0; i < 40; i = i + 1 ) {
            let ret = false;
            for (const value of this.data.inputs){
                if (value.input === i) {
                    ret = true;
                    break;
                }
            }
            if (!ret) {
                this.clearWindow(i);
            }
        }

        for (let i = 0; i < 40; i = i + 1) {
            let ret = false;
            for (const value of this.data.labels){
                if (value.id === i) {
                    ret = true;
                    break;
                }
            }
            if (!ret) {
                this.clearWindow(100 + i);
            }
        }

        // окна
        this.data.inputs.forEach( (value: WindowConfig, i: number) => {
            let fontSize = '1em';
            if ((!value.update) && (!drawAll)){
                return;
            }
            value.update = false;
            this.clearWindow(value.input);
            const g = this.draw.group().attr('index', value.input);
            const boxSize: Rect = this.getWindowBoxSize(value.pos);
            const r = g.rect(boxSize.w, boxSize.h).attr({ fill: this.colorActive })
            .move(boxSize.x, boxSize.y)
            .click(() => {
                this.router.navigate(['/edit/window/' + i]);
            });
            if ((value.pos.scale_x === 0) && (this.gridSize === 12)) {
                fontSize = '0.5em';
            }
            // Имя входа
            const text = g.plain(this.shortName(this.wsdata.getInputName(value.input)))
            .font({ fill: '#ffffff', 'font-size': fontSize, 'text-anchor': 'middle' })
            .center(boxSize.x + boxSize.w / 2, boxSize.y + boxSize.h - textOffset)
            .attr('pointer-events', 'none');

            // иконка
            g.use('closeicon').size(closeSize, closeSize)
            .center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5);

            g.rect(closeSize, closeSize).center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5)
            .attr('pointer-events', 'bounding-box')
            .opacity(0.01)
            .click(() => this.removeWindow(value.pos));
        });

        // часы
        if (this.wsdata.clockData.enable) {
            if (this.wsdata.clockData.update || drawAll) {
                let clockSize = 50;
                if (((this.wsdata.clockData.pos.scale_x === 0) || (this.wsdata.clockData.pos.scale_y === 0))
                    && (this.gridSize === 12)) {
                    clockSize = 10;
                }
                this.wsdata.clockData.update = false;
                this.clearWindow(-1);
                const g = this.draw.group().attr('index', -1);
                const boxSize: Rect = this.getWindowBoxSize(this.wsdata.clockData.pos);
                const r = g.rect(boxSize.w, boxSize.h).attr({ fill: this.colorActive })
                .move(boxSize.x, boxSize.y)
                .click(() => {
                    this.router.navigate(['/edit/clock']);
                });

                g.use('clock').size(clockSize, clockSize).center(boxSize.x + boxSize.w / 2, boxSize.y + boxSize.h / 2)
                .attr('pointer-events', 'none');

                // иконка
                g.use('closeicon').size(closeSize, closeSize)
                .center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5);

                g.rect(closeSize, closeSize).center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5)
                .attr('pointer-events', 'bounding-box')
                .opacity(0.01)
                .click(() => this.removeWindow(this.wsdata.clockData.pos));
            }
        } else {
            this.clearWindow(-1);
        }

        // Таймер
        if (this.wsdata.timerData.enable) {
            if (this.wsdata.timerData.update || drawAll) {
                let fontSize = '1em';
                if ((this.wsdata.timerData.pos.scale_x === 0) && (this.gridSize === 12)) {
                    fontSize = '0.5em';
                }
                this.wsdata.timerData.update = false;
                this.clearWindow(-2);
                const g = this.draw.group().attr('index', -2);
                const boxSize: Rect = this.getWindowBoxSize(this.wsdata.timerData.pos);
                const r = g.rect(boxSize.w, boxSize.h).attr({ fill: this.colorActive })
                .move(boxSize.x, boxSize.y);

                // иконка
                g.use('closeicon').size(closeSize, closeSize)
                .center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5);

                const text = g.plain(this.shortName('Timer'))
                .font({ fill: '#ffffff', 'font-size': fontSize, 'text-anchor': 'middle' })
                .center(boxSize.x + boxSize.w / 2, boxSize.y + boxSize.h - textOffset)
                .attr('pointer-events', 'none');

                g.rect(closeSize, closeSize).center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5)
                .attr('pointer-events', 'bounding-box')
                .opacity(0.01)
                .click(() => this.removeWindow(this.wsdata.timerData.pos));
            }
        } else {
            this.clearWindow(-2);
        }

        // Метки
        this.data.labels.forEach( (value: LabelConfig, i: number) => {
            let fontSize = '1em';
            if ((!value.update) && (!drawAll)){
                return;
            }
            value.update = false;
            this.clearWindow(100 + value.id);
            const g = this.draw.group().attr('index', 100 + value.id);
            const boxSize: Rect = this.getWindowBoxSize(value.pos);
            const r = g.rect(boxSize.w, boxSize.h).attr({ fill: this.colorActive })
            .move(boxSize.x, boxSize.y)
            .click(() => {
                this.router.navigate(['/edit/label/' + i]);
            });
            if ((value.pos.scale_x === 0) && (this.gridSize === 12)) {
                fontSize = '0.5em';
            }
            // Имя входа
            const text = g.plain(this.shortName(value.text))
            .font({ fill: '#ffffff', 'font-size': fontSize, 'text-anchor': 'middle' })
            .center(boxSize.x + boxSize.w / 2, boxSize.y + boxSize.h - textOffset)
            .attr('pointer-events', 'none');

            // иконка
            g.use('closeicon').size(closeSize, closeSize)
            .center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5);

            g.rect(closeSize, closeSize).center(boxSize.x + boxSize.w - closeSize / 2 - 5, boxSize.y + closeSize / 2 + 5)
            .attr('pointer-events', 'bounding-box')
            .opacity(0.01)
            .click(() => this.removeWindow(value.pos));
        });

    }

    clearWindow(index: number): void {
        const children = this.draw.children();
        for (const value of children){
            if (value.attr('index') === index) {
                value.remove();
                break;
            }
        }
    }

    updateState(): void {
        this.draw.children().each( (e) => e.fire('update') );
    }

    newWindow(value: WindowPos): void {
        this.changed.emit(value);
    }

    isInside(left: number, scale: number, value: number): boolean {
        if ((value >= left) && (value <= left + scale)) {
            return true;
        }
        if ((value <= left) && (value >= left + scale)) {
            return true;
        }
        return false;
    }

    isSelected(pos: WindowPos, v: GridPos): boolean {
        return this.isInside(pos.x, pos.scale_x, v.x) && this.isInside(pos.y, pos.scale_y, v.y);
    }

    getDirection(scale): number {
        if (Math.sign(scale) >= 0) {
            return 1;
        } else {
            return -1;
        }
    }

    getEndPos(v: GridPos): WindowPos {
        const width = v.x - this.selectStart.x;
        const height = v.y - this.selectStart.y;
        let scaleX = 0;
        let scaleY = 0;
        scaleX = Math.abs(width);
        scaleY = Math.abs(height);

        const endXtmp = this.selectStart.x + this.getDirection(width) * scaleX;
        const endYtmp = this.selectStart.y + this.getDirection(height) * scaleY;

        return {x: endXtmp, y: endYtmp, scale_x: scaleX, scale_y: scaleY};
    }

    validScale(v: GridPos): boolean {
        const endPos = this.getEndPos(v);

        if ((endPos.x >= this.data.grid) || (endPos.x < 0)) {
            return false;
        }
        if ((endPos.y >= this.data.grid) || (endPos.y < 0)) {
            return false;
        }

        const w = this.convertSelection(v);

        if (this.getAnyWindowIntersect(w)) {
            return false;
        }
        return true;
    }

    convertSelection(v: GridPos): WindowPos {
        const endPos = this.getEndPos(v);
        const pos = {
            x: Math.min(this.selectStart.x, endPos.x),
            y: Math.min(this.selectStart.y, endPos.y),
            scale_x: endPos.scale_x,
            scale_y: endPos.scale_y,
        };
        return pos;
    }

    selectDone(v: GridPos): void {
        if (this.selectState === 0) {
            return;
        }
        this.selectState = 0;

        let ret = 0;
        const rect = this.convertSelection(this.selectEnd);
        this.data.inputs.forEach( (value: WindowConfig, i: number) => {
            if (this.isWindowIntersecting(rect, value.pos) || (!this.validScale(this.selectEnd))) {
                ret = 1;
            }
        });
        if (ret === 0) {
            this.newWindow(rect);
        }
        this.updateState();
    }

    gridMouseDown(data, v: GridPos): void {
        this.selectState = 1;
        this.selectStart = v;
        this.selectEnd = v;
        this.updateState();
    }

    gridMouseUp(v: GridPos): void {
        this.selectDone(v);
    }

    bkgMouseUp(): void {
        this.selectDone(this.selectEnd);
    }

    gridUpdate(data, v: GridPos): void {
        const e = SVG(data.target);

        const pos = this.convertSelection(this.selectEnd);

        if (this.isSelected(pos, v) && this.selectState) {
            e.attr({ fill: this.colorNew });
        } else {
            e.attr({ fill: this.colorGrid });
        }
    }

    gridMouseOut(data, v: GridPos): void {
    }

    gridMouseOver(data: MouseEvent, v: GridPos): void {
        if (data.buttons === 1) {
            if (this.validScale(v) && this.selectState) {
                this.selectEnd = v;
                this.updateState();
            }
        } else {
            this.selectState = 0;
        }
    }

    removeWindow(v: WindowData): void {
        this.remove.emit(v);
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.data === undefined) {
            return;
        }
        if (!changes.data.isFirstChange()) {
            this.drawLayout();
        }
    }
}
