import { Component, AfterViewInit, ViewChild } from '@angular/core';
import { NgForm } from '@angular/forms';
import { WsdataService } from '../wsdata.service';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
    selector: 'app-main',
    templateUrl: './main.component.html',
    styleUrls: ['./main.component.less']
})
export class MainComponent implements AfterViewInit {

    @ViewChild('statusForm', {static: false}) statusForm: NgForm;

    public settingsData = this.wsData.settingsData;
    public diagnosticsData = this.wsData.diagnosticsData;


    newdata(): void {
        this.settingsData = this.wsData.copySettings();
        if (this.wsData.settingsData.cascade_mode === 5) {
            this.router.navigate(['/system']);
        }
    }

    constructor(public wsData: WsdataService, private router: Router) {
        this.wsData.subscribeNewData(() => this.newdata());
    }

    ngAfterViewInit(): void {
        this.newdata();
    }

    soloOnChange(value: {enable: number, input: number}): void {
        this.wsData.settingsData.solo.enable = value.enable;
        this.wsData.settingsData.solo.input = value.input;
        this.wsData.sendSolo();
    }

    public presetChanged(preset: number): void {
        this.wsData.sendPreset(preset);
    }

}
